Perf
| where $__timeFilter(TimeGenerated)
| where WindowApproved and TimeGenerated>=IntervalEnd-4h and TimeGenerated<IntervalEnd
| where Computer in~ ('HV-HOST-01')
| where isempty(tolower(tostring(column_ifexists('_ResourceId','')))) or tolower(tostring(column_ifexists('_ResourceId',''))) startswith '/subscriptions/<SUBSCRIPTION_ID>/resourcegroups/rg-hyperv-arc-monitor-demo/'
| extend Computer=toupper(Computer)
| where ObjectName=='Hyper-V Hypervisor Virtual Processor'
    and CounterName in ('% Total Run Time','CPU Wait Time Per Dispatch')
| where InstanceName!='_Total' and InstanceName contains ':Hv VP'
| extend Guest=toupper(tostring(split(InstanceName,':')[0]))
| where Guest in ('SQL2019-GUEST','WIN2019-GUEST','WIN2022-GUEST','WIN2025-GUEST-01','RHEL94-GUEST')
| where isfinite(CounterValue) and CounterValue>=0
| summarize MeanCpuPct=avgif(CounterValue,CounterName=='% Total Run Time'),
    PeakCpuPct=maxif(CounterValue,CounterName=='% Total Run Time'),
    P95WaitNs=percentile(iff(CounterName=='CPU Wait Time Per Dispatch',CounterValue,real(null)),95),
    OccupiedBuckets=dcount(bin(TimeGenerated,1m)),LastSample=max(TimeGenerated) by Guest,Vcpu=InstanceName
| order by PeakCpuPct desc nulls last
